head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gLastJob = "";
scwin.seq = frame.opener.scwin.seq;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        frame.width = 630;
        frame.height = 775;

        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        scwin.setShowObj();
        cmb_SANCTN_AMT_IMPOST_TP_CD.setValue("");
        cmb_DISCLS_VIOL_MOTIV_TP_CD.setValue("");
        cmb_DISCLS_VIOL_SIGNIF_TP_CD.setValue("");
        if (scwin.seq !== "") {
            scwin.readInfo();
        } else {
            await scwin.setSaveHeader();

            // fn_setComiteSeq();

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35151.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        if (scwin.seq !== "") {
            await scwin.update();
        } else {
            await scwin.save();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35151.btn_Save_onclick" });
    }
};

