/**
 * @method
 * @name validCheck
 * @description valid Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validCheck = async function() {
    if (txb_isur_cd.getValue() === '') {
        await $c.win.alert("[회사코드]를 입력하세요.");
        txb_isur_cd.focus();
        return false;
    }
    if (edt_COMITE_DD.getValue() === '') {
        await $c.win.alert("[위원회 일시]를 입력하세요.");
        edt_COMITE_DD.focus();
        return false;
    }
    if (txb_COMITE_SEQ.getValue() !== '' && !$c.ut.isNum(txb_COMITE_SEQ.getValue())) {
        await $c.win.alert("숫자만 입력가능합니다.");
        txb_COMITE_SEQ.focus();
        return false;
    }
    if (!$c.ut.isDate(edt_COMITE_DD.getValue(), '')) {
        await $c.win.alert("[위원회 일시]를 확인해 주세요.");
        edt_COMITE_DD.focus();
        return false;
    }
    if (edt_NFAITHDISCLS_DESIGN_DD.getValue() !== '' && !$c.ut.isDate(edt_NFAITHDISCLS_DESIGN_DD.getValue(), '')) {
        await $c.win.alert("[지정여부 일자]를 확인해 주세요.");
        edt_NFAITHDISCLS_DESIGN_DD.focus();
        return false;
    }
    if (edt_TRD_HALT_DD.getValue() !== '' && !$c.ut.isDate(edt_TRD_HALT_DD.getValue(), '')) {
        await $c.win.alert("[매매거래정지 일자]를 확인해 주세요.");
        edt_TRD_HALT_DD.focus();
        return false;
    }
    if (edt_NFAITHDISCLS_REAL_INVSTG_DD.getValue() !== '' && !$c.ut.isDate(edt_NFAITHDISCLS_REAL_INVSTG_DD.getValue(), '')) {
        await $c.win.alert("[실질심사 일자]를 확인해 주세요.");
        edt_NFAITHDISCLS_REAL_INVSTG_DD.focus();
        return false;
    }
    if (!await scwin.checkNumber(txb_DELIB_BAS_PNLT)) return false;
    if (!await scwin.checkNumber(txb_WT_PNLT)) return false;
    if (!await scwin.checkNumber(txb_REDU_PNLT)) return false;
    if (!await scwin.checkNumber(txb_IMPOST_PNLT)) return false;
    if (!await scwin.checkNumber(txb_ACC_PNLT)) return false;
    if (!await scwin.checkNumber(txb_DISCLS_VIOL_SANCTN_AMT)) return false;
    return true;
};

