        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name isNumJum
 * @description is Num Jum 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.isNumJum = function(str) {
    let cnt = 0;
    for (i = 0; i < str.length; i++) {
        const cv = str.charCodeAt(i);
        if (i === 0 || i === str.length - 1) {
            if (!(0x30 <= cv && cv <= 0x39)) {
                return false;
            }
        } else {
            if (!((0x30 <= cv && cv <= 0x39) || cv === 0x2E)) {
                return false;
            } else {
                if (cv === 0x2E) {
                    cnt++;
                }
            }
        }
    }
    if (cnt > 1) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name alert_error2
 * @description alert error2 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지
                await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지
                await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
